/*
 * A029406  Expansion of 1/((1-x^5)*(1-x^8)*(1-x^10)*(1-x^11)).
 * https://oeis.org/A029406
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = number of partitions of n into parts 5, 8, 10, and 11.
 *            The sequence is generated by dynamic programming over the
 *            available part sizes. For each part size p in increasing order
 *            we add the number of partitions that end with that part. This
 *            counts each unordered combination exactly once
 * Range:     u8 n <= 69, u16 n <= 69, u32 n <= 69, u64 n <= 69, u128 n <= 69,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

static seq_t *cache = NULL;   /* DP table a[0..N] */
static idx_t cache_size = 0;  /* number of elements stored (N+1) */

/* Recompute the DP table up to index n (inclusive). */
static void recompute(idx_t n)
{
    seq_t *tmp = (seq_t *)realloc(cache, (n + 1) * sizeof(seq_t));
    if (!tmp) abort();
    cache = tmp;

    /* Initialize all entries to 0. */
    for (idx_t i = 0; i <= n; ++i)
        cache[i] = 0;

    cache[0] = (seq_t)1;   /* base case: one way to sum to 0 */

    const idx_t parts[4] = {5, 8, 10, 11};
    for (int pi = 0; pi < 4; ++pi) {
        idx_t p = parts[pi];
        for (idx_t i = p; i <= n; ++i) {
            cache[i] += cache[i - p];
        }
    }

    cache_size = n + 1;
}

/* Function required by the build system */
seq_t a(idx_t n)
{
    if (n + 1 > cache_size)
        recompute(n);
    else
        /* Even if n is within the existing cache, the table may have
           been left from a previous reallocation that did not enlarge
           it to the required size.  The check above guarantees we
           always have a complete table up to n. */
        ;
    return cache[n];
}
